from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import HwscanURI


class HwscanV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_hwscan_address_ranges(self, timeout=60):
        uri = HwscanURI().hwscan_range_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def create_hwscan_address_range(self, first_addr, last_addr, timeout=60, **kwargs):
        data = {"first_addr": first_addr,
                "last_addr": last_addr,
                **kwargs}
        uri = HwscanURI().hwscan_range_uri
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def delete_hwscan_address_range(self, range_id, timeout=60):
        uri = HwscanURI().hwscan_range_id_uri + '/' + range_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def initiate_hwscan(self, range_id, timeout=60):
        data = {"responseType": "json"}
        uri = HwscanURI().hwscan_range_id_uri + '/' + range_id
        return self.api_client.send_put_request(uri=uri, json=data, timeout=timeout)

    def get_devices_from_hwscan_range(self, range_id, timeout=60):
        uri = HwscanURI().hwscan_devices_range_uri + '/' + range_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)
